function solve({config,state,event}){
  let s=state;
  if(s===null)s={ttl:config.ttl,ps:[config.parties[0],config.parties[1]],now:0,token:null,expires:null,approved:[],connected:null};
  let expired=false;
  if(s.expires!==null&&s.now>=s.expires){s.token=null;s.expires=null;s.approved=[];s.connected=null;expired=true}
  let status='ignored',t=event&&event.type;
  if(t==='advance'){
    s.now+=event.dt;
    if(s.expires!==null&&s.now>=s.expires){s.token=null;s.expires=null;s.approved=[];s.connected=null;expired=true}
    status='advanced';
  }else if(t==='offer'){
    s.token=event.token;s.expires=s.now+s.ttl;s.approved=[];s.connected=null;status='offered';
  }else if(t==='accept'){
    if(s.token!==null&&s.connected===null&&event.token===s.token&&(event.party===s.ps[0]||event.party===s.ps[1])){
      if(s.approved.indexOf(event.party)>=0)status='duplicate';
      else{s.approved.push(event.party);s.approved.sort();status='accepted';if(s.approved.length===2){s.connected=s.token;s.expires=null;status='connected'}}
    }
  }else if(t==='cancel'){
    if(s.token!==null&&event.token===s.token){s.token=null;s.expires=null;s.approved=[];s.connected=null;status='cancelled'}
  }
  return {state:s,output:{status:status,now:s.now,token:s.token,expires:s.expires,approved:s.approved.slice(),connected:s.connected,expired:expired}};
}
